/* NCFC regional-partner accent — canary + green, light touch */
.masthead .sig { color: var(--ncfc-green); }
.masthead .sig-text { background-image: linear-gradient(105deg, var(--ncfc-green) 42%, #dff3d9 50%, var(--ncfc-green) 58%); }
.kicker { color: var(--ncfc-green); }
.zone .num { color: var(--ncfc-green); }
.stats strong { color: var(--ncfc-green); }
.plan .tag { background: var(--ncfc-gold); border-color: var(--ncfc-gold); color: #14532d; }

vec3 col = texture2D(u_tex, cuv).rgb;
      // NCFC accent: unresolved mosaic tiles checkerboard canary/green,
      // fading back to the real photo as the paper resolves.
      float lum = dot(col, vec3(0.299, 0.587, 0.114));
      float chk = mod(floor(vUv.x * cells) + floor(vUv.y * cells), 2.0);
      vec3 ncfc = mix(vec3(1.0, 0.89, 0.05), vec3(0.0, 0.55, 0.24), chk);
